const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || payload.payload?.message || {};

const chatId = source.chatId || message.chat?.id || payload.chatId || payload.payload?.chatId || '';
const raw = String(source.rawText || source.text || message.text || message.caption || payload.text || payload.rawText || '').trim();

const document = source.document || message.document || payload.document || payload.payload?.document || payload.payload?.message?.document || null;
const video = source.video || message.video || payload.video || payload.payload?.video || payload.payload?.message?.video || null;
const audio = source.audio || message.audio || message.voice || payload.audio || payload.payload?.audio || payload.payload?.message?.audio || payload.payload?.message?.voice || null;
const photo = source.photo || message.photo || payload.photo || payload.payload?.photo || payload.payload?.message?.photo || null;

const photoItem = Array.isArray(photo) && photo.length ? photo[photo.length - 1] : photo;

const telegramFileId = source.fileId || document?.file_id || video?.file_id || audio?.file_id || photoItem?.file_id || '';
const fileName = source.fileName || document?.file_name || video?.file_name || audio?.file_name || (photoItem?.file_id ? `telegram-photo-${photoItem.file_id}.jpg` : 'upload.bin');
const mimeType = source.mimeType || document?.mime_type || video?.mime_type || audio?.mime_type || (photoItem?.file_id ? 'image/jpeg' : 'application/octet-stream');
const folderId = source.folderId || payload.folderId || 'root';
const binaryPropertyName = 'data';

const hasTarget = Boolean(telegramFileId);

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    telegramFileId,
    fileId: telegramFileId,
    fileName,
    mimeType,
    folderId,
    binaryPropertyName,
    hasTarget,
    response: hasTarget ? '' : 'Bạn hãy gửi kèm file/ảnh rồi nhập caption: upload file này vào drive'
  }
}];

const source = $('Prepare Action').item.json || {};
const result = $input.item.json?.result || {};
const filePath = result.file_path || '';
if (!filePath) {
  return [{ json: { ...source, response: 'Không lấy được file_path từ Telegram getFile.' } }];
}
return [{
  json: {
    ...source,
    telegramFilePath: filePath,
    telegramDownloadUrl: `https://api.telegram.org/file/bot${$env.TELEGRAM_BOT_TOKEN}/${filePath}`
  }
}];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const source = $('Prepare Action').item.json || {};
const item = $input.item.json || {};
const fileName = item.name || source.fileName || 'Không rõ tên';
const fileId = item.id || '';
const link = item.webViewLink || (fileId ? `https://drive.google.com/file/d/${fileId}/view` : '');
const mimeType = item.mimeType || source.mimeType || '';

let text = '✅ <b>Đã upload file lên Google Drive</b>\n\n';
text += `📄 <b>${escapeHtml(fileName)}</b>\n`;
if (mimeType) text += `Loại: <code>${escapeHtml(mimeType)}</code>\n`;
if (fileId) text += `ID: <code>${escapeHtml(fileId)}</code>\n`;
if (link) text += `🔗 <a href="${escapeHtml(link)}">Mở file</a>`;

return [{ json: { chatId: source.chatId || item.chatId, text: text.trim() } }];
